#include <stdio.h>

/* imparesFora le um inteiro N e imprime 1..N, um por linha, deixando de
   fora os multiplos de 3.
   O laco ja esta pronto e hoje ele imprime TODOS os numeros.
   Falta pular a volta dos multiplos de 3: um if com % e, dentro dele,
   o continue. */
void imparesFora(void) {
    int n = 0;
    scanf("%d", &n);

    for (int i = 1; i <= n; i++) {
        /* pule aqui a volta quando i for multiplo de 3 */

        printf("%d\n", i);
    }
}

